exercises.starter:
int pages = int.Parse(Console.ReadLine()!);
int copies = int.Parse(Console.ReadLine()!);
int sheetPrice = int.Parse(Console.ReadLine()!);

// Сначала найди расход бумаги на один экземпляр.

exercises.solution:
int pages = int.Parse(Console.ReadLine()!);
int copies = int.Parse(Console.ReadLine()!);
int sheetPrice = int.Parse(Console.ReadLine()!);

int sheetsPerCopy = (pages + 3) / 4;
int totalSheets = sheetsPerCopy * copies;
int blankPages = (sheetsPerCopy * 4 - pages) * copies;
int cost = totalSheets * sheetPrice;
Console.WriteLine($"Листов: {totalSheets}");
Console.WriteLine($"Пустых страниц: {blankPages}");
Console.WriteLine($"Стоимость: {cost}");

