// Обработай оба визита по порядку, сохраняя остаток штампов.

exercises.solution:
int size = int.Parse(Console.ReadLine()!);
int stamps = int.Parse(Console.ReadLine()!);
int firstVisit = int.Parse(Console.ReadLine()!);
int secondVisit = int.Parse(Console.ReadLine()!);

stamps += firstVisit;
int firstGifts = stamps / size;
stamps %= size;

stamps += secondVisit;
int secondGifts = stamps / size;
stamps %= size;

Console.WriteLine($"Первый визит: {firstGifts}");
Console.WriteLine($"Второй визит: {secondGifts}");
Console.WriteLine($"Всего подарков: {firstGifts + secondGifts}");
Console.WriteLine($"Остаток: {stamps}");

