// Выдели нужную четвёрку битов и подготовь маску изменений.

exercises.solution:
int panel = int.Parse(Console.ReadLine()!);
int row = int.Parse(Console.ReadLine()!);
int pattern = int.Parse(Console.ReadLine()!);

const int rowMask = 0b1111;
int shift = row * 4;
int previous = (panel >> shift) & rowMask;
int updated = (panel & ~(rowMask << shift)) | (pattern << shift);
int changed = panel ^ updated;

Console.WriteLine($"Было в ряду: {previous:B4}");
Console.WriteLine($"Табло: {updated:B8}");
Console.WriteLine($"Изменились: {changed:B8}");

