// Обработай два запроса одним методом TryGive.

exercises.solution:
int fives = Convert.ToInt32(Console.ReadLine());
int twos = Convert.ToInt32(Console.ReadLine());
for (int request = 0; request < 2; request++)
{
    int amount = Convert.ToInt32(Console.ReadLine());
    bool ok = TryGive(amount, ref fives, ref twos, out int issued);
    Console.WriteLine(ok ? $"Выдано {issued}" : "Отказ");
}
Console.WriteLine($"Осталось {fives} {twos}");

static bool TryGive(int amount, ref int fives, ref int twos, out int issued)
{
    issued = 0;
    if (amount <= 0)
        return false;

    for (int useFives = Math.Min(fives, amount / 5); useFives >= 0; useFives--)
    {
        int rest = amount - 5 * useFives;
        if (rest % 2 != 0 || rest / 2 > twos)
            continue;
        int useTwos = rest / 2;
        fives -= useFives;
        twos -= useTwos;
        issued = useFives + useTwos;
        return true;
    }
    return false;
}

