exercises.solution:
int length = Convert.ToInt32(Console.ReadLine());
Console.WriteLine(Ways(length));

static int Ways(int length)
{
    return Count(length, false);

    static int Count(int remaining, bool lastWasLong)
    {
        if (remaining == 0)
            return 1;
        int ways = Count(remaining - 1, false);
        if (!lastWasLong && remaining >= 2)
            ways += Count(remaining - 2, true);
        return ways;
    }
}

