static int LengthNeeded(int gap = 2, params int[] lengths)
{
    int total = 0;
    bool hasPatch = false;
    foreach (int length in lengths)
    {
        if (length == 0) continue;
        if (hasPatch) total += gap;
        total += length;
        hasPatch = true;
    }
    return total;
}

