{
    int start = 0;
    while (start < beads.Count)
    {
        int end = start + 1;
        while (end < beads.Count && beads[end] == beads[start]) end++;
        if (end - start >= 3)
        {
            beads.RemoveRange(start, end - start);
            break;
        }
        start = end;
    }
    if (start == beads.Count) break;
}
