static IEnumerable<int> SilenceLengths(string track)
{
    int silence = 0;
    foreach (char sample in track)
    {
        if (sample == '0') silence++;
        else if (silence > 0)
        {
            yield return silence;
            silence = 0;
        }
    }
    if (silence > 0) yield return silence;
}

