string indices = string.Join(" ", Changed(before, levels, start));
Console.WriteLine(indices.Length == 0 ? "Нет изменений" : indices);

static IEnumerable<int> Changed(int[] before, int[] after, int start)
{
    for (int i = 0; i < before.Length; i++)
        if (before[i] != after[start + i]) yield return start + i;
}

