var first = new Flask(int.Parse(Console.ReadLine()), int.Parse(Console.ReadLine()));
var second = new Flask(int.Parse(Console.ReadLine()), int.Parse(Console.ReadLine()));
int forward = int.Parse(Console.ReadLine());
int back = int.Parse(Console.ReadLine());

Console.WriteLine(first.PourTo(second, forward));
Console.WriteLine(second.PourTo(first, back));
Console.WriteLine($"{first.Volume} {second.Volume}");

class Flask
{
    public int Capacity { get; }
    public int Volume { get; private set; }

    public Flask(int capacity, int volume)
    {
        Capacity = capacity;
        Volume = volume;
    }

    public int PourTo(Flask other, int requested)
    {
        int space = other.Capacity - other.Volume;
        int moved = Math.Min(requested, Math.Min(Volume, space));
        Volume -= moved;
        other.Volume += moved;
        return moved;
    }
}

