{
    // Учти тираж листовки.
    public int Sheets() => 0;
}

exercises.solution:
int paper = int.Parse(Console.ReadLine());
int count = int.Parse(Console.ReadLine());
int accepted = 0;
for (int i = 0; i < count; i++)
{
    IPrintOrder order = ReadOrder();
    int sheets = order.Sheets();
    if (sheets <= paper)
    {
        paper -= sheets;
        accepted++;
    }
}
Console.WriteLine($"{accepted} {paper}");

static IPrintOrder ReadOrder()
{
    string[] parts = Console.ReadLine().Split(' ');
    if (parts[0] == "доклад")
        return new Report(int.Parse(parts[1]), int.Parse(parts[2]));
    return new Flyer(int.Parse(parts[1]));
}

interface IPrintOrder { int Sheets(); }

record Report(int Pages, int Copies) : IPrintOrder
{
    public int Sheets() => ((Pages + 1) / 2) * Copies;
}

record Flyer(int Copies) : IPrintOrder
{
    public int Sheets() => Copies;
}

