static Photo ReadPhoto()
{
    string name = Console.ReadLine();
    string[] parts = Console.ReadLine().Split(' ');
    int points = int.Parse(parts[1]);
    if (parts[0] == "зрители")
        return new AudiencePhoto(name, points, int.Parse(parts[2]));
