        return new LatePhoto(name, points);
    return new Photo(name, points);
}

class Photo
{
    public string Name { get; }
    private readonly int points;
    public Photo(string name, int points)
    {
        Name = name;
        this.points = points;
    }
    public virtual int Score() => points;
}

class AudiencePhoto : Photo
{
    private readonly int votes;
    public AudiencePhoto(string name, int points, int votes) : base(name, points)
        => this.votes = votes;
    public override int Score() => base.Score() + Math.Min(3, votes / 5);
}

class LatePhoto : Photo
{
    public LatePhoto(string name, int points) : base(name, points) { }
    public override int Score() => Math.Max(0, base.Score() - 2);
}

