using static System.Math;

namespace Studio.Devices;

public class Metronome
{
    public int Bpm { get; private set; }
    public Metronome(int start) => Bpm = start;

    public bool Change(int delta)
    {
        int requested = Bpm + delta;
        Bpm = Max(40, Min(200, requested));
        return Bpm == requested;
    }
}

