using Games.Models;

namespace Games.Reports;

public static class EveningPlan
{
    public static int CountFits(Round[] rounds, int limit)
    {
        int played = 0;
        foreach (Round round in rounds)
        {
            if (round.Minutes > limit) break;
            limit -= round.Minutes;
            played++;
        }
        return played;
    }
}

