using Trail.Models;

namespace Trail.Reports;

public static class ClimbReport
{
    public static int BestClimb(Waypoint[] stops, out int rise)
    {
        rise = 0;
        int best = -1;
        for (int i = 0; i + 1 < stops.Length; i++)
        {
            int change = stops[i + 1].Height - stops[i].Height;
            if (change > rise)
            {
                best = i;
                rise = change;
            }
        }
        return best;
    }
}

