using BikeHire.Core;

int days = int.Parse(Console.ReadLine());
int total = 0;
int passes = 0;
for (int day = 0; day < days; day++)
{
    int trips = int.Parse(Console.ReadLine());
    int singles = 0;
    for (int i = 0; i < trips; i++)
    {
        int minutes = int.Parse(Console.ReadLine());
        singles += BikeFare.Single(minutes);
    }
    if (singles > BikeFare.DayPass)
    {
        total += BikeFare.DayPass;
        passes++;
    }
    else
    {
        total += singles;
    }
}
Console.WriteLine($"Всего: {total}");
Console.WriteLine($"Дней с абонементом: {passes}");

