    else
        Console.WriteLine(token.TryTake(out int number) ? number.ToString() : "Пусто");
}

class Cell<T>
{
    private T current = default!;
    private bool occupied;

    public bool TryStore(T value)
    {
        if (occupied) return false;
        current = value;
        occupied = true;
        return true;
    }

    public bool TryTake(out T value)
    {
        value = current;
        if (!occupied) return false;
        current = default!;
        occupied = false;
        return true;
    }
}

