static int LongestRun<T>(T[] items) where T : IComparable<T>
{
    if (items.Length == 0) return 0;
    int current = 1;
    int best = 1;
    for (int i = 1; i < items.Length; i++)
    {
        current = items[i].CompareTo(items[i - 1]) >= 0 ? current + 1 : 1;
        if (current > best) best = current;
    }
    return best;
}

readonly record struct Medal(int Rank) : IComparable<Medal>
{
    public int CompareTo(Medal other) => Rank.CompareTo(other.Rank);
}

