    void Add(int value);
    int Result { get; }
}

class Receipts : IStatistic
{
    public int Result { get; private set; }
    public void Add(int value)
    {
        if (value > 0) Result += value;
    }
}

class PeakBalance : IStatistic
{
    private int balance;
    public int Result { get; private set; }

    public void Add(int value)
    {
        balance += value;
        if (balance > Result) Result = balance;
    }
}

