exercises.solution:
int threshold = int.Parse(Console.ReadLine()!);
int count = int.Parse(Console.ReadLine()!);
var tank = new Tank(threshold);
bool listening = true;
tank.Reached += Sound;
for (int i = 0; i < count; i++)
{
    string command = Console.ReadLine()!;
    if (command == "тихо")
    {
        if (listening) tank.Reached -= Sound;
        listening = false;
    }
    else if (command == "слушать")
    {
        if (!listening) tank.Reached += Sound;
        listening = true;
    }
    else tank.Change(int.Parse(command));
}
Console.WriteLine($"Остаток {tank.Volume}");

static void Sound(int volume) => Console.WriteLine($"Сигнал {volume}");

class Tank
{
    private readonly int threshold;
    public int Volume { get; private set; }
    public event Action<int> Reached = delegate { };
    public Tank(int threshold) => this.threshold = threshold;

    public void Change(int amount)
    {
        int old = Volume;
        Volume = Math.Max(0, Volume + amount);
        if (old < threshold && Volume >= threshold) Reached(Volume);
    }
}

