var rating = rounds.GroupBy(r => r.Team)
    .Where(group => group.Count() >= 2)
    .Select(group =>
    {
        int[] scores = group.Select(r => r.Score).OrderByDescending(score => score).ToArray();
        return new { Team = group.Key, Total = scores[0] + scores[1] };
