exercises.solution:
int box = int.Parse(Console.ReadLine()!);
int count = int.Parse(Console.ReadLine()!);
int area = 0;
int calculations = 0;
Lazy<int> estimate = NewEstimate();
for (int i = 0; i < count; i++)
{
    string[] words = Console.ReadLine()!.Split(' ');
    if (words[0] == "участок") area += int.Parse(words[1]);
    else if (words[0] == "смета") Console.WriteLine(estimate.Value);
    else estimate = NewEstimate();
}
Console.WriteLine($"Расчётов {calculations}");

Lazy<int> NewEstimate() => new Lazy<int>(() =>
{
    calculations++;
    return (int)Math.Ceiling((decimal)area / box);
});

