int[] bounds = Array.ConvertAll(Console.ReadLine()!.Split(' '), int.Parse);
int width = bounds[0], height = bounds[1];
int count = int.Parse(Console.ReadLine()!);
(int X, int Y) point = (0, 0);

int rejected = 0;
for (int i = 0; i < count; i++)
{
    string[] words = Console.ReadLine()!.Split(' ', StringSplitOptions.RemoveEmptyEntries);
    if (words is ["домой"])
    {
        point = (0, 0);
        continue;
    }
    (string Direction, int Steps) move = words switch
    {
        ["шаг", var d] => (d, 1),
        ["шаг", var d, var raw] when int.TryParse(raw, out int n) && n is >= 1 and <= 100 => (d, n),
        _ => ("", 0)
    };
    var (dx, dy) = move.Direction switch
    {
        "В" => (1, 0),
        "З" => (-1, 0),
        "С" => (0, 1),
        "Ю" => (0, -1),
        _ => (0, 0)
    };
    int x = point.X + dx * move.Steps;
    int y = point.Y + dy * move.Steps;
    if ((dx, dy) == (0, 0) || x < 0 || x >= width || y < 0 || y >= height)
        rejected++;
    else point = (x, y);
}
Console.WriteLine($"{point.X} {point.Y}");
Console.WriteLine(rejected);

