static void Inspect(string[] signals)
{
    int checkedCount = 0;
    try
    {
        foreach (string signal in signals)
        {
            checkedCount++;
            try
            {
                BeltScanner.Scan(checkedCount, signal);
            }
            catch (ScanFault error) when (error.CanSkip)
            {
