public sealed class ScanFault(int position, bool canSkip) : Exception
{
    public int Position { get; } = position;
    public bool CanSkip { get; } = canSkip;
}

public static class BeltScanner
{
    public static void Scan(int position, string signal)
    {
        if (signal == "размыто") throw new ScanFault(position, true);
        if (signal == "сбой") throw new ScanFault(position, false);
    }
}

