const string first = "morning-copy.txt";
const string second = "evening-copy.txt";
const string restored = "restored-list.txt";
Copies.Prepare(first, second);
int unresolved = Restore(first, second, restored);
foreach (string line in File.ReadAllLines(restored)) Console.WriteLine(line);
Console.WriteLine($"Нерешённых строк {unresolved}");

static int Restore(string first, string second, string destination)
{
    string[] left = File.ReadAllLines(first);
    string[] right = File.ReadAllLines(second);
    var merged = new string[left.Length];
    int unresolved = 0;
    for (int i = 0; i < merged.Length; i++)
    {
        if (left[i] == "" && right[i] == "")
        {
            merged[i] = "[пропуск]";
            unresolved++;
        }
        else if (left[i] == "") merged[i] = right[i];
        else if (right[i] == "" || left[i] == right[i]) merged[i] = left[i];
        else
        {
            merged[i] = "[сверить]";
            unresolved++;
        }
    }
    File.WriteAllLines(destination, merged);
    return unresolved;
}

