exercises.solution:
string oldRoot = Snapshot.Read();
string newRoot = Snapshot.Read();

var before = Sizes(oldRoot);
var after = Sizes(newRoot);
bool changed = false;
var paths = before.Keys.Union(after.Keys).OrderBy(path => path, StringComparer.Ordinal);
foreach (string path in paths)
{
    bool existed = before.TryGetValue(path, out long oldSize);
    bool exists = after.TryGetValue(path, out long newSize);
    if (!existed) Console.WriteLine($"новый {path}");
    else if (!exists) Console.WriteLine($"удалён {path}");
    else if (oldSize != newSize) Console.WriteLine($"размер {path}: {oldSize} -> {newSize}");
    else continue;
    changed = true;
}
if (!changed) Console.WriteLine("Без изменений");

static Dictionary<string, long> Sizes(string root)
{
    return Directory.EnumerateFiles(root, "*", SearchOption.AllDirectories)
        .ToDictionary(
            path => Path.GetRelativePath(root, path).Replace(Path.DirectorySeparatorChar, '/'),
            path => new FileInfo(path).Length,
            StringComparer.Ordinal);
}

