using System.IO.Compression;

using var parcel = RegistrationZip.Read();
using var archive = new ZipArchive(parcel, ZipArchiveMode.Read);
var counters = new Dictionary<string, int>(StringComparer.Ordinal);
foreach (var entry in archive.Entries)
{
    if (!entry.FullName.StartsWith("groups/", StringComparison.Ordinal) ||
        !entry.FullName.EndsWith(".txt", StringComparison.Ordinal)) continue;
    var names = new HashSet<string>(StringComparer.Ordinal);
    using var reader = new StreamReader(entry.Open());
    while (reader.ReadLine() is string line)
    {
        string name = line.Trim();
        if (name.Length > 0) names.Add(name);
    }
    foreach (string name in names)
    {
        counters.TryGetValue(name, out int count);
        counters[name] = count + 1;
    }
}
var matches = counters.Where(pair => pair.Value >= 2)
    .OrderBy(pair => pair.Key, StringComparer.Ordinal).ToList();
if (matches.Count == 0) Console.WriteLine("Совпадений нет");
foreach (var pair in matches) Console.WriteLine($"{pair.Key} — {pair.Value}");

