using System.IO.Compression;
using System.Text;

public static class RegistrationZip
{
    public static MemoryStream Read()
    {
        int count = int.Parse(Console.ReadLine()!);
        var parcel = new MemoryStream();
        using (var zip = new ZipArchive(parcel, ZipArchiveMode.Create, leaveOpen: true))
        {
            for (int i = 0; i < count; i++)
            {
                string path = Console.ReadLine()!;
                int lines = int.Parse(Console.ReadLine()!);
                var entry = zip.CreateEntry(path, CompressionLevel.NoCompression);
                using var writer = new StreamWriter(entry.Open(), new UTF8Encoding(false));
                for (int line = 0; line < lines; line++) writer.WriteLine(Console.ReadLine());
            }
        }
        parcel.Position = 0;
        return parcel;
    }
}

