using System.Text.Json.Nodes;

string original = Console.ReadLine()!;
SettingsAudit.Show(original, Migrate(original));

static string Migrate(string original)
{
    var settings = JsonNode.Parse(original)!.AsObject();
    var seen = new HashSet<string>(StringComparer.Ordinal);
    var result = new JsonArray();
    if (settings["stops"] is JsonArray stops)
    {
        foreach (var item in stops) AddStop(item!.GetValue<string>());
    }
    AddStop(settings["favorite"]?.GetValue<string>() ?? "");
    settings.Remove("favorite");
    settings["stops"] = result;
    return settings.ToJsonString();

    void AddStop(string text)
    {
        string name = text.Trim();
        if (name.Length > 0 && seen.Add(name)) result.Add(name);
    }
}

