using System.Text.Json.Nodes;

public static class SettingsAudit
{
    public static void Show(string original, string migrated)
    {
        var before = JsonNode.Parse(original)!.AsObject();
        var after = JsonNode.Parse(migrated)!.AsObject();
        if (after.ContainsKey("favorite") || after["stops"] is not JsonArray stops)
        {
            Console.WriteLine("Проверь формат остановок");
            return;
        }
        var values = stops.Select(item => item!.GetValue<string>()).ToArray();
        Console.WriteLine(values.Length == 0 ? "Остановок нет" : string.Join(" / ", values));
        before.Remove("favorite");
        before.Remove("stops");
        after.Remove("stops");
        Console.WriteLine(JsonNode.DeepEquals(before, after)
            ? "Прочие настройки сохранены" : "Прочие настройки изменены");
    }
}

