files.Rack.cs:
public class Rack
{
    private readonly int capacity;
    private readonly string version;
    public int Free { get; private set; }

    public Rack(int capacity, string version)
    {
        this.capacity = capacity;
        this.version = version;
        Free = capacity;
    }

    public bool Take(int count)
    {
        bool allowed = version == "B" ? count < Free : count <= Free;
        if (!allowed)
        {
            if (version == "C") Free = 0;
            return false;
        }
        Free = (version == "D" ? capacity : Free) - count;
        return true;
    }
}

