int capacity = Convert.ToInt32(Console.ReadLine());
int first = Convert.ToInt32(Console.ReadLine());
int second = Convert.ToInt32(Console.ReadLine());
int count = Convert.ToInt32(Console.ReadLine());
List<int> groups = [];
for (int i = 0; i < count; i++)
    groups.Add(Convert.ToInt32(Console.ReadLine()));

var kiln = new Kiln(capacity);
Console.WriteLine($"Проба {kiln.Batches(first, second)}");
Console.WriteLine($"Заказ {kiln.Batches(groups)}");

class Kiln(int capacity)
{
    public int Batches(params IReadOnlyList<int> groups)
    {
        int batches = 0;
        int free = 0;
        foreach (int group in groups)
        {
            if (group > capacity)
                return -1;
            if (group > free)
            {
                batches++;
                free = capacity;
            }
            free -= group;
        }
        return batches;
    }
}

