static Preview MakePreview(string note, int width)
{
    if (note.Length == 0)
        return new EmptyNote();
    if (note.Length <= width)
        return new FullNote(note);
    return new CutNote(note[..width], note.Length - width);
}

record EmptyNote;
record FullNote(string Text);
record CutNote(string Prefix, int Omitted);
union Preview(EmptyNote, FullNote, CutNote);

int commands = Convert.ToInt32(Console.ReadLine());
WatchState state = new Paused(0);
for (int i = 0; i < commands; i++)
{
    int time = Convert.ToInt32(Console.ReadLine());
    string command = Console.ReadLine()!;
    state = Apply(state, command, time);
}
int finish = Convert.ToInt32(Console.ReadLine());
Console.WriteLine(state switch
{
    Paused paused => $"На паузе {paused.Elapsed}",
    Running running => $"Идёт {running.Elapsed + finish - running.Since}"
});

static WatchState Apply(WatchState state, string command, int time)
{
    return (state, command) switch
    {
        (_, "сброс") => new Paused(0),
        (Paused paused, "старт") => new Running(paused.Elapsed, time),
        (Running running, "пауза") => new Paused(running.Elapsed + time - running.Since),
        _ => state
    };
}

closed record class WatchState;
sealed record class Paused(int Elapsed) : WatchState;
sealed record class Running(int Elapsed, int Since) : WatchState;

