exercises.solution:
string[] requirements = ReadCodes();
HashSet<string> required = [with(StringComparer.OrdinalIgnoreCase), .. requirements];
int count = Convert.ToInt32(Console.ReadLine());
int bestIndex = 0;
int fewestExtra = int.MaxValue;
search: for (int index = 1; index <= count; index++)
{
    HashSet<string> seen = [with(StringComparer.OrdinalIgnoreCase)];
    foreach (string code in ReadCodes())
    {
        if (!seen.Add(code))
            continue search;
    }
    if (!required.IsSubsetOf(seen))
        continue;

    int extra = seen.Count - required.Count;
    if (extra < fewestExtra)
    {
        bestIndex = index;
        fewestExtra = extra;
        if (extra == 0)
            break search;
    }
}
Console.WriteLine(bestIndex == 0 ? "Нет набора" : $"Набор {bestIndex}, лишних {fewestExtra}");

static string[] ReadCodes()
{
    return (Console.ReadLine() ?? "").Split(' ', StringSplitOptions.RemoveEmptyEntries);
}

