{
    string number = Console.ReadLine()!.Trim();
    string category = Console.ReadLine()!.Trim();
    string text = Console.ReadLine()!;
    if (number.Length == 0 || category.Length == 0 || !int.TryParse(text, out int amount) || amount <= 0)
    {
        invalid++;
        continue;
