public sealed record Expense(int Amount, string Category);

public static class ExpenseInput
{
    public static List<Expense> ReadAll()
    {
        int count = int.Parse(Console.ReadLine()!);
        var expenses = new List<Expense>();
        for (int i = 0; i < count; i++)
        {
            string category = Console.ReadLine()!;
            int amount = int.Parse(Console.ReadLine()!);
            expenses.Add(new Expense(amount, category));
        }
        return expenses;
    }
}

exercises.solution:
var expenses = ExpenseInput.ReadAll();
if (expenses.Count == 0)
{
    Console.WriteLine("Расходов нет");
    return;
}
var groups = expenses.GroupBy(expense => expense.Category, StringComparer.OrdinalIgnoreCase)
    .Select(group => new { Name = group.Key, Total = group.Sum(item => (long)item.Amount) })
    .OrderByDescending(group => group.Total)
    .ThenBy(group => group.Name, StringComparer.Ordinal)
    .ToList();
long total = groups.Sum(group => group.Total);
long covered = 0;
long? cutoff = null;
foreach (var group in groups)
{
    if (cutoff.HasValue && group.Total < cutoff.Value) break;
    Console.WriteLine($"{group.Name} — {group.Total}");
    covered += group.Total;
