exercises.solution:
using System.Text.Json;
using ExpenseTracker;

const string backup = "family-backup.json";
const string incoming = "family-import.json";
var journal = new Ledger();
bool hasBackup = false;
int count = int.Parse(Console.ReadLine()!);
for (int i = 0; i < count; i++)
{
    var parts = Console.ReadLine()!.Trim().Split(' ', 2, StringSplitOptions.RemoveEmptyEntries);
    string value = parts.Length == 2 ? parts[1].Trim() : "";
    switch (parts[0])
    {
        case "трата":
            var fields = value.Split(' ', 2, StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
            if (fields.Length == 2 && int.TryParse(fields[0], out int amount) && amount > 0)
            {
                journal.Add(amount, fields[1]);
                Console.WriteLine("Добавлено");
            }
            else Console.WriteLine("Ошибка записи");
            break;
        case "копия":
            journal.Save(backup);
            hasBackup = true;
            Console.WriteLine("Копия сохранена");
            break;
        case "откат":
            if (hasBackup)
            {
                journal.Load(backup);
                Console.WriteLine("Копия восстановлена");
            }
            else Console.WriteLine("Нет копии");
            break;
        case "импорт":
            File.WriteAllText(incoming, value);
            bool loaded;
            try { loaded = journal.Load(incoming); }
            catch (JsonException) { loaded = false; }
            Console.WriteLine(loaded ? "Импорт принят" : "Импорт отклонён");
            break;
        case "категория":
            Console.WriteLine($"По категории {journal.TotalFor(value)}");
            break;
    }
}
Console.WriteLine($"Всего {journal.Total}");

