exercises.solution:
using System.Globalization;

var shifts = new List<(DateTime Start, DateTime End)>();
int count = int.Parse(Console.ReadLine()!);
int skipped = 0;
for (int i = 0; i < count; i++)
{
    string[] parts = (Console.ReadLine() ?? "").Split('/');
    if (parts.Length == 2 && TryTime(parts[0], out var start)
        && TryTime(parts[1], out var end) && end > start)
        shifts.Add((start, end));
    else skipped++;
}

TimeSpan covered = TimeSpan.Zero;
if (shifts.Count > 0)
{
    var ordered = shifts.OrderBy(shift => shift.Start).ToArray();
    var (start, end) = ordered[0];
    for (int i = 1; i < ordered.Length; i++)
    {
        var next = ordered[i];
        if (next.Start > end)
        {
            covered += end - start;
            (start, end) = next;
        }
        else if (next.End > end) end = next.End;
    }
    covered += end - start;
}
Console.WriteLine(covered.Ticks / TimeSpan.TicksPerMinute);
Console.WriteLine(skipped);

static bool TryTime(string text, out DateTime value)
{
    return DateTime.TryParseExact(text, "yyyy-MM-dd HH:mm",
        CultureInfo.InvariantCulture, DateTimeStyles.None, out value);
}

