static int Transfer(Sections stock, int from, int to, int amount)
{
    if (from < 1 || from > stock.Count || to < 1 || to > stock.Count || from == to)
        return 0;

    ref int source = ref stock.At(from);
    ref int destination = ref stock.At(to);
    int moved = Math.Min(amount, source);
    source -= moved;
    destination += moved;
    return moved;
}

class Sections
{
    private readonly int[] amounts;
