int count = 0;
using var bothRead = new Barrier(2);
var gate = new System.Threading.Lock();

RunPair(AddBroken);
Console.WriteLine(count);
count = 0;
RunPair(AddSafe);
Console.WriteLine(count);

void AddBroken()
{
    int old = Volatile.Read(ref count);
    bothRead.SignalAndWait();
    Volatile.Write(ref count, old + 1);
}
void AddSafe()
{
    lock (gate) { count++; }
}
static void RunPair(ThreadStart add)
{
    var first = new Thread(add);
    var second = new Thread(add);
    first.Start();
    second.Start();
    first.Join();
    second.Join();
}

object gate = new();
int stock = 0;
var smallBox = new Thread(() =>
{
    lock (gate) { stock += 3; }
});
var bigBox = new Thread(() =>
{
    bool entered = false;
    try
    {
        Monitor.Enter(gate, ref entered);
        stock += 4;
    }
    finally
    {
        if (entered) Monitor.Exit(gate);
    }
});
smallBox.Start();
bigBox.Start();
smallBox.Join();
bigBox.Join();
Console.WriteLine(stock);

