string[] orderedCodes = Console.ReadLine()!.Split(' ', StringSplitOptions.RemoveEmptyEntries);
string[] printedCodes = Console.ReadLine()!.Split(' ', StringSplitOptions.RemoveEmptyEntries);

// Сравни частоты всех кодов из двух тиражей.

exercises.solution:
string[] orderedCodes = Console.ReadLine()!.Split(' ', StringSplitOptions.RemoveEmptyEntries);
string[] printedCodes = Console.ReadLine()!.Split(' ', StringSplitOptions.RemoveEmptyEntries);

var ordered = CountCodes(orderedCodes);
var printed = CountCodes(printedCodes);
var codes = ordered.Keys.Union(printed.Keys).OrderBy(code => code, StringComparer.Ordinal);
bool matches = true;
foreach (string code in codes)
{
    int missing = ordered.GetValueOrDefault(code) - printed.GetValueOrDefault(code);
    if (missing == 0) continue;
    matches = false;
    Console.WriteLine(missing > 0 ? $"{code} не хватает {missing}" : $"{code} лишних {-missing}");
}
if (matches) Console.WriteLine("Тираж совпал");

static Dictionary<string, int> CountCodes(string[] codes) => codes
    .GroupBy(code => code, StringComparer.Ordinal)
    .ToDictionary(group => group.Key, group => group.Count(), StringComparer.Ordinal);

