#nullable enable
using System.Dynamic;

public static class RouteCard
{
    public static ExpandoObject Read(string minutes, string hours)
    {
        var result = new ExpandoObject();
        IDictionary<string, object?> fields = result;
        Add("Minutes", minutes);
        Add("Hours", hours);
        return result;

        void Add(string key, string value)
        {
            if (value == "-") return;
            if (int.TryParse(value, out int number) && number is >= 0 and <= 120) fields[key] = number;
            else fields[key] = value;
        }
    }
}

