exercises.solution:
int count = int.Parse(Console.ReadLine()!);
Type contract = typeof(Gallery.ITile);

var assembly = contract.Assembly;
var activated = new HashSet<Type>();
for (int i = 0; i < count; i++)
{
    string name = Console.ReadLine()!;
    var type = assembly.GetType(name);
    if (type is null || !type.IsPublic || !type.IsClass || type.IsAbstract ||
        !contract.IsAssignableFrom(type)) continue;
    var constructor = type.GetConstructor(Type.EmptyTypes);
    if (constructor is null || !activated.Add(type)) continue;
    var tile = (Gallery.ITile)constructor.Invoke([]);
    Console.WriteLine(tile.Caption());
}
Console.WriteLine($"Запущено {activated.Count}");

