// Выбери известную модель и передай её тип в PrintSchema.

static void PrintSchema(Type model, string kind)
{
    // Укажи требуемые члены в аннотации и собери схему.
}

exercises.solution:
using System.Diagnostics.CodeAnalysis;
using System.Reflection;

string key = Console.ReadLine()!;
string kind = Console.ReadLine()!;

switch (key)
{
    case "посылка": PrintSchema(typeof(Parcel), kind); break;
    case "кадр": PrintSchema(typeof(Frame), kind); break;
    default: Console.WriteLine("Неизвестная модель"); break;
}

static void PrintSchema(
    [DynamicallyAccessedMembers(DynamicallyAccessedMemberTypes.PublicFields |
        DynamicallyAccessedMemberTypes.PublicProperties)] Type model, string kind)
{
    const BindingFlags flags = BindingFlags.Public | BindingFlags.Instance;
    var members = kind == "поля"
        ? model.GetFields(flags).Select(field => (field.Name, Type: field.FieldType))
        : model.GetProperties(flags).Select(property => (property.Name, Type: property.PropertyType));
    var sorted = members.OrderBy(member => member.Name, StringComparer.Ordinal).ToArray();
    if (sorted.Length == 0) Console.WriteLine("Нет членов");
    foreach (var member in sorted)
        Console.WriteLine($"{member.Name} {member.Type.Name}");
}

